import java.sql.*;
import java.util.*;
public class JdbcTransfer{static Integer balance(Connection c,int id)throws SQLException{try(PreparedStatement p=c.prepareStatement("SELECT id, name, balance FROM users WHERE id = ?")){p.setInt(1,id);try(ResultSet r=p.executeQuery()){return r.next()?r.getInt("balance"):null;}}}static void set(Connection c,int id,int value)throws SQLException{try(PreparedStatement p=c.prepareStatement("UPDATE users SET balance = ? WHERE id = ?")){p.setInt(1,value);p.setInt(2,id);p.executeUpdate();}}public static void main(String[]a)throws Exception{Scanner s=new Scanner(System.in);int from=s.nextInt(),to=s.nextInt(),amount=s.nextInt();try(Connection c=MiniJdbc.open()){c.setAutoCommit(false);Integer fb=balance(c,from),tb=balance(c,to);if(fb==null||tb==null||amount<=0||fb<amount){c.rollback();System.out.println("送金失敗");return;}set(c,from,fb-amount);set(c,to,tb+amount);c.commit();System.out.println("from="+(fb-amount)+" to="+(tb+amount));}}}

